function loadState() { try { const parsed = JSON.parse(localStorage.getItem(STORAGE)); if (parsed?.version === 1 && Array.isArray(parsed.orders) && Array.isArray(parsed.calls) && Array.isArray(parsed.events)) return parsed; } catch { storageFailed = true; } return Q.seed(); }
let state = loadState();
let search = '', historyFilter = 'all', audioEnabled = false, toastTimer, publicPage = 0;
let knownCalls = new Set(state.calls.map(c => c.id));
