  history: '<path d="M3 10a9 9 0 1 1 1.5 7M3 4v6h6m3-4v6l4 2"/>',
  settings: '<path d="m10 3-.5 3-2 1.2L4.6 6l-2 3.5L5 11v2l-2.4 1.5 2 3.5 2.9-1.2 2 1.2.5 3h4l.5-3 2-1.2 2.9 1.2 2-3.5L19 13v-2l2.4-1.5-2-3.5-2.9 1.2-2-1.2L14 3z"/><circle cx="12" cy="12" r="3"/>',
  help: '<circle cx="12" cy="12" r="9"/><path d="M9.5 8.5a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 4h.01"/>',
  arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
