  connection: '<path d="M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0m-9 4a4.5 4.5 0 0 1 6 0m-3 4h.01"/>',
  power: '<path d="M12 2v10M6.3 5.3a9 9 0 1 0 11.4 0"/>',
  coffee: '<path d="M3 8h13v7a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5V8Zm13 1h2a3 3 0 0 1 0 6h-2M6 2v3m4-3v3m4-3v3M2 22h16"/>',
  close: '<path d="m6 6 12 12M6 18 18 6"/>',
