const eventLabels = { registered:'Registrado', ready:'Marcado listo', delivered:'Entregado', repeat:'Nuevo llamado', correct:'Corregido a preparación', cancel:'Cancelado' };
function historyRows() {
 const events = [...state.events].sort((a,b) => b.at-a.at).filter(e => (historyFilter === 'all' || e.action === historyFilter) && (!search || e.number.includes(search.trim())));
 return events.length ? events.map(e => `<tr><td class="number-cell">#${e.number}</td><td><span class="event-badge ${e.action}">${icon(e.action === 'repeat' ? 'audio' : e.action === 'delivered' ? 'check' : 'clock')}${eventLabels[e.action] || 'Actualizado'}</span></td><td>${escapeHtml(e.actor)}</td><td>${time(e.at)} <small class="muted">· ${new Date(e.at).toLocaleDateString('es-MX',{day:'numeric',month:'short'})}</small></td></tr>`).join('') : '<tr><td colspan="4" class="table-empty">No hay movimientos que coincidan.</td></tr>';
}
function historyView() {
 return shell(`${heading('Historial de pedidos', 'Cada registro, llamado y entrega, en un solo lugar.')}<section class="wide-card"><div class="list-toolbar"><h2>Movimientos <span class="muted">· ${state.events.length}</span></h2><select id="history-filter" class="history-filter" aria-label="Filtrar movimientos">${[['all','Todos los movimientos'],...Object.entries(eventLabels)].map(([value,label]) => `<option value="${value}" ${historyFilter === value ? 'selected' : ''}>${label}</option>`).join('')}</select><div class="search-wrap">${icon('search')}<input type="search" id="history-search" aria-label="Buscar ticket en historial" placeholder="Buscar ticket…" value="${escapeHtml(search)}"></div></div><div class="table-wrap"><table class="history-table"><thead><tr><th scope="col">Ticket</th><th scope="col">Movimiento</th><th scope="col">Operador</th><th scope="col">Fecha y hora</th></tr></thead><tbody id="history-rows">${historyRows()}</tbody></table></div></section><p class="subtitle">Un número puede repetirse al cerrar un pedido. Cada registro conserva su propio historial.</p>`);
}
function settingsView() {
 const opened = state.orders.filter(Q.active).length;
 return shell(`${heading('Configuración', 'Prepara tu espacio antes de comenzar la jornada.')}<div class="settings-grid"><section class="wide-card settings-card"><h2>Audio y pantalla</h2><p>Los llamados se reproducen en un solo dispositivo. Las tres pantallas muestran el mismo contenido.</p><div class="setting-row"><div><strong>Anuncios en español</strong><small>${audioEnabled ? 'Activados en esta pestaña' : 'Desactivados en esta pestaña'}</small></div><button class="toggle ${audioEnabled ? 'on' : ''}" role="switch" aria-checked="${audioEnabled}" aria-label="Activar voz" data-action="audio"></button></div><div class="setting-row"><div><strong>Prueba de sonido</strong><small>Comprueba que las bocinas se escuchen.</small></div><button class="button small" data-action="test-audio">${icon('audio')}Probar</button></div><div class="setting-row"><div><strong>Pantalla de clientes</strong><small>Abre otra ventana para ver los cambios en vivo.</small></div><a class="button small" href="#pantalla" target="_blank" rel="noopener">${icon('link')}Abrir</a></div></section><section class="wide-card settings-card"><h2>Jornada de caja</h2><p>Los pedidos se conservan al recargar. Antes de cerrar, resuelve todos los pedidos activos.</p><div class="setting-row"><div><strong>${state.sessionOpen ? 'Jornada en curso' : 'Jornada cerrada'}</strong><small>${opened} pedidos activos · Caja 01</small></div><span class="status-line"><i class="status-dot"></i>${state.sessionOpen ? 'Abierta' : 'Cerrada'}</span></div><div class="setting-row"><div><strong>${state.sessionOpen ? 'Cerrar jornada' : 'Comenzar jornada'}</strong><small>El historial de pedidos se conserva.</small></div><button class="button small" data-action="session">${icon('power')}${state.sessionOpen ? 'Cerrar' : 'Abrir'}</button></div><div class="setting-row"><div><strong>Acceso a caja</strong><small>Entrada simulada para esta demostración.</small></div><button class="button small" data-action="signout">Ver acceso</button></div></section><section class="wide-card settings-card"><h2>Probar una desconexión</h2><p>Pausa la conexión simulada para ver los avisos y la recuperación de la pantalla.</p><div class="setting-row"><div><strong>Conexión de la demo</strong><small>${state.connected ? 'Los cambios se reflejan al instante.' : 'Operación pausada. Usa el llamado manual.'}</small></div><button class="toggle ${state.connected ? 'on' : ''}" role="switch" aria-checked="${state.connected}" aria-label="Conexión simulada" data-action="connection"></button></div><p class="subtitle">Si falla el equipo real: conserva los tickets impresos y anuncia verbalmente desde caja.</p></section><section class="wide-card settings-card"><h2>Datos de demostración</h2><p>Prueba el flujo con pedidos de ejemplo. Puedes volver al estado inicial cuando lo necesites.</p><div class="setting-row"><div><strong>Restablecer pedidos de ejemplo</strong><small>Reemplaza los cambios de esta demo.</small></div><button class="button small" data-action="reset">${icon('undo')}Restablecer</button></div><div class="setting-row"><div><strong>Recorrido de operación</strong><small>Registro, cocina, llamado y entrega.</small></div><button class="button small" data-action="help">${icon('help')}Ver guía</button></div></section></div><div class="demo-notice"><strong>Acerca de esta demostración.</strong> Interfaz en HTML, CSS y JavaScript. Usa almacenamiento de este navegador y voz disponible en el equipo. El acceso es simulado. La autenticación real, servidor local, SQLite, sincronización entre equipos y montaje de tres televisores requieren la implementación posterior. La voz sin internet depende de disponer de una voz española local.</div>`);
}
function publicView() {
 const latest=Q.latest(state), ready=Q.ready(state), other=ready.filter(o=>o.id!==latest?.orderId), pages=Math.max(1,Math.ceil(other.length/8));
 publicPage%=pages; const shown=other.slice(publicPage*8,publicPage*8+8);
 return `<div class="public-view"><header class="public-header"><div>${brand()}<div class="brand-caption">CAFETERÍA · FACULTAD DE INFORMÁTICA</div></div><div class="public-tools"><span class="clock" data-clock>${time(Date.now())}</span><button class="button small" data-action="audio" aria-label="${audioEnabled ? 'Desactivar' : 'Activar'} audio" aria-pressed="${audioEnabled}">${icon(audioEnabled?'audio':'mute')}<span>${audioEnabled?'Audio activado':'Activar audio'}</span></button><button class="button small" data-action="fullscreen" aria-label="Pantalla completa">${icon('expand')}</button><a class="button small" href="#caja" aria-label="Volver a caja">${icon('grid')}<span>Volver a caja</span></a></div></header>${connectionBanner()}<main id="main" class="public-main" aria-label="Pedidos listos para recoger"><h1>${latest?'Tu pedido está listo':'Bienvenido a Comal++'}</h1>${latest?`<div class="public-number" aria-label="Último llamado: ticket ${latest.number}">${latest.number}</div><p class="public-instruction">Recoge tu pedido presentando tu ticket</p><section class="public-ready" aria-label="También listos para recoger"><h2 class="public-ready-label">${other.length?'También listos para recoger':'Te esperamos en el mostrador'}</h2><div class="public-number-grid">${shown.map(o=>`<span>${o.number}</span>`).join('')}</div>${pages>1?`<p class="public-pagination">${publicPage+1} de ${pages} · Los números cambian automáticamente cada 6 segundos</p>`:''}</section>`:'<div class="public-empty">Estamos preparando<br>tus pedidos</div><p class="public-instruction">Mantén tu ticket a la mano. Te avisaremos aquí.</p>'}</main><footer class="public-footer"><span>Comal++ · Facultad de Informática, UAQ</span><span>${ready.length} ${ready.length===1?'pedido listo':'pedidos listos'} para recoger</span><span>Demostración · ${state.connected?'Pantalla sincronizada':'Conexión pausada'}</span></footer></div>`;
}
function loginView() {
 return `<main id="main" class="login-view"><section class="login-card"><div class="login-brand">${brand()}<div class="brand-caption">CAFETERÍA · FI UAQ</div></div><div class="eyebrow">ESPACIO DE TRABAJO</div><h1>Todo listo para comenzar.</h1><p class="subtitle">Entra al panel de caja y acompaña cada pedido hasta su entrega.</p><div class="demo-account"><div class="avatar">C1</div><div><strong>Caja 01</strong><small>Operador de demostración</small></div>${icon('shield')}</div><button class="button primary" data-action="signin">Entrar a la demo ${icon('arrow')}</button><a class="preview-link" href="#pantalla">${icon('monitor')}Abrir pantalla pública</a><p class="login-note">Acceso simulado. No se requieren credenciales reales.</p></section><p class="login-footer">Comal++ · Facultad de Informática · UAQ</p></main>`;
}
function render() {
 const focus=document.activeElement;
 const preserved = focus?.tagName==='INPUT' ? {id:focus.id,value:focus.value,start:focus.selectionStart,end:focus.selectionEnd} : null;
 const r=route();
 app.innerHTML=r==='pantalla'?publicView():!signedIn?loginView():r==='historial'?historyView():r==='ajustes'?settingsView():cashier();
 if(preserved){const next=document.getElementById(preserved.id);if(next){next.value=preserved.value;next.focus({preventScroll:true});try{next.setSelectionRange(preserved.start,preserved.end);}catch{}}}
 document.title=`Comal++ · ${r==='pantalla'?'Listos para recoger':r==='historial'?'Historial':r==='ajustes'?'Configuración':'Panel de caja'}`;
}
function audioOwner() { try { return JSON.parse(localStorage.getItem(AUDIO_STORAGE)); } catch { return null; } }
function setAudio(enabled) {
 if(enabled && !('speechSynthesis' in window)){toast('Este navegador no admite voz. Anuncia los pedidos desde caja.',true);return;}
 const owner=audioOwner();
 if(enabled && owner && owner.id!==tabId && Date.now()-owner.at<10000){toast('El audio ya está activo en otra pestaña. Desactívalo allí antes de usar esta.',true);return;}
 audioEnabled=enabled;
 if(enabled){try{localStorage.setItem(AUDIO_STORAGE,JSON.stringify({id:tabId,at:Date.now()}));}catch{}}
 else {audioQueue=[];speaking=false;currentUtterance=null;window.speechSynthesis?.cancel();try{if(owner?.id===tabId)localStorage.removeItem(AUDIO_STORAGE);}catch{}}
 render();
 if(enabled)speak('Comal más más. Audio activado. Pedido veintiocho, favor de pasar a recoger.');
}
function processCalls() { for(const call of state.calls){if(!knownCalls.has(call.id)){knownCalls.add(call.id);if(audioEnabled && state.connected && state.orders.some(o=>o.id===call.orderId&&o.status==='ready'))audioQueue.push({text:`Pedido ${Number(call.number)}, favor de pasar a recoger.`,orderId:call.orderId});}} pumpAudio(); }
function speak(text) { audioQueue.push({text});pumpAudio(); }
function pumpAudio() {
 if(speaking||!audioEnabled||!('speechSynthesis' in window))return;
 let item=audioQueue.shift();while(item?.orderId&&!state.orders.some(o=>o.id===item.orderId&&o.status==='ready'))item=audioQueue.shift();if(!item)return;
 const u=new SpeechSynthesisUtterance(item.text);u.lang='es-MX';u.rate=.94;const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang.startsWith('es')&&v.localService)||voices.find(v=>v.lang.startsWith('es'));if(voice)u.voice=voice;
 speaking=true;currentUtterance=u;
 const finish=()=>{if(currentUtterance!==u)return;speaking=false;currentUtterance=null;pumpAudio();};u.onend=finish;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('No se pudo reproducir el audio. Usa el llamado verbal y vuelve a probar.',true);finish();};speechSynthesis.speak(u);
}
function showModal(title, content, actions='') {
 document.getElementById('modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}`;
 if(!modal.open)modal.showModal();
}
function help() {
 showModal('De caja al mostrador',`<p class="modal-copy">El mismo ticket de siempre, con un llamado más claro.</p><div class="help-steps">${[['Registra el ticket','Cobra e imprime como de costumbre. Captura su número del 01 al 99.'],['Cocina prepara','El pedido queda en preparación. Cocina avisa a caja cuando está completo.'],['Marca listo','La pantalla muestra el número y lo anuncia si el audio está activado. Puedes volver a llamarlo.'],['Confirma la entrega','El cliente presenta su ticket. Pulsa Entregado para retirarlo de la pantalla.']].map(([title,copy])=>`<div class="help-step"><div><strong>${title}</strong><p>${copy}</p></div></div>`).join('')}</div><div class="demo-notice">Usa ··· para corregir o cancelar. Si el sistema falla, conserva los tickets y anuncia verbalmente. En Configuración puedes probar la desconexión y restablecer esta demo.</div>`,`<button class="button primary" data-action="close-modal">Entendido ${icon('check')}</button>`);
}
app.addEventListener('submit', e => { if(e.target.id !== 'ticket-form') return; e.preventDefault(); const input = document.getElementById('ticket-input'); try { syncLatest(); const order = Q.register(state,input.value); persist(); input.value=''; search=''; render(); toast(`Ticket ${order.number} registrado. En preparación.`); document.getElementById('ticket-input')?.focus(); } catch(err) { const hint=document.getElementById('entry-hint'); hint.className='form-hint error'; hint.textContent=err.message; input.setAttribute('aria-invalid','true'); input.focus(); } });
app.addEventListener('input', e => { if(e.target.id === 'search') { search=e.target.value; document.getElementById('board').innerHTML=orderBoard(); } if(e.target.id==='history-search'){search=e.target.value;document.getElementById('history-rows').innerHTML=historyRows();} });
app.addEventListener('change',e=>{if(e.target.id==='history-filter'){historyFilter=e.target.value;document.getElementById('history-rows').innerHTML=historyRows();}});
document.addEventListener('click', e => { const button = e.target.closest('[data-action]'); if(!button) return; e.preventDefault(); handleAction(button.dataset.action,button.dataset.id); });
function handleAction(action,id) {
 const order=state.orders.find(o=>o.id===id);
 if(['ready','delivered','repeat'].includes(action)) {
   if(!signedIn||route()==='pantalla')return;
   mutate(()=>Q.transition(state,id,action),{ready:`Ticket ${order?.number} listo para recoger.`,delivered:`Ticket ${order?.number} entregado. ¡Buen provecho!`,repeat:`Nuevo llamado para el ticket ${order?.number}.`}[action]);
 } else if(action==='audio'||action==='test-audio') {if(action==='test-audio'&&audioEnabled)speak('Comal más más. Prueba de audio. Pedido veintiocho, favor de pasar a recoger.');else setAudio(action==='test-audio'||!audioEnabled);}
 else if(action==='close-modal')modal.close();
 else if(action==='help')help();
 else if(action==='more'&&order&&signedIn)showModal(`Ticket ${order.number}`,`<p class="modal-copy" style="margin-bottom:18px">${order.status==='ready'?'Listo para recoger':'En preparación'} · ${elapsed(order.createdAt)}</p><div class="action-list">${order.status==='ready'?`<button class="button" data-action="confirm-correct" data-id="${id}">${icon('undo')}Volver a preparación</button>`:''}<button class="button soft" data-action="confirm-cancel" data-id="${id}">${icon('close')}Cancelar pedido</button></div>`);
 else if(['confirm-correct','confirm-cancel'].includes(action)&&order&&signedIn){const cancel=action==='confirm-cancel';showModal(`${cancel?'Cancelar':'Corregir'} ticket ${order.number}`,`<p class="modal-copy">${cancel?'Este pedido se retirará de la lista activa. Esta acción no modifica el cobro ni procesa una devolución.':'El pedido volverá a preparación y se retirará de la pantalla pública. Si ya se anunció, avisa al cliente desde caja.'}</p>`,`<button class="button" data-action="close-modal">Volver</button><button class="button ${cancel?'danger':'primary'}" data-action="${cancel?'cancel':'correct'}" data-id="${id}">${cancel?'Sí, cancelar pedido':'Volver a preparación'}</button>`);}
 else if(['cancel','correct'].includes(action)&&signedIn&&route()!=='pantalla'){modal.close();mutate(()=>Q.transition(state,id,action),action==='cancel'?`Ticket ${order?.number} cancelado.`:`Ticket ${order?.number} vuelve a preparación.`);}
 else if(action==='connection'&&signedIn&&route()!=='pantalla'){syncLatest();state.connected=!state.connected;persist();if(!state.connected){audioQueue=[];window.speechSynthesis?.cancel();speaking=false;currentUtterance=null;}else knownCalls=new Set(state.calls.map(c=>c.id));render();toast(state.connected?'Conexión recuperada. La lista está actualizada.':'Conexión pausada para esta demostración.');}
 else if(action==='session'&&signedIn){const count=state.orders.filter(Q.active).length;if(state.sessionOpen)showModal('Cerrar jornada',`<p class="modal-copy">${count?`Hay ${count} pedidos activos. Entrega o cancela esos pedidos antes de cerrar la jornada.`:'Todos los pedidos están resueltos. El historial se conservará al cerrar.'}</p>`,`<button class="button" data-action="close-modal">Volver</button>${count?'':'<button class="button primary" data-action="close-session">Cerrar jornada</button>'}`);else showModal('Abrir jornada','<p class="modal-copy">Comienza una nueva jornada. Los pedidos anteriores seguirán disponibles en el historial.</p>','<button class="button" data-action="close-modal">Volver</button><button class="button primary" data-action="open-session">Abrir jornada</button>');}
 else if(action==='close-session'&&signedIn){modal.close();mutate(()=>{Q.closeSession(state);return true;},'Jornada cerrada. Historial conservado.');}
 else if(action==='open-session'&&signedIn){modal.close();mutate(()=>{if(!state.connected)throw new Error('Reconecta la demo antes de abrir la jornada.');state.sessionOpen=true;state.sessionStarted=Date.now();return true;},'Nueva jornada abierta.');}
 else if(action==='reset'&&signedIn)showModal('Restablecer la demo','<p class="modal-copy">Se reemplazarán todos los pedidos y movimientos de esta demostración por los datos de ejemplo iniciales, en las pestañas de este navegador.</p>','<button class="button" data-action="close-modal">Conservar cambios</button><button class="button primary" data-action="reset-confirm">Restablecer demo</button>');
 else if(action==='reset-confirm'&&signedIn){modal.close();state=Q.seed();knownCalls=new Set(state.calls.map(c=>c.id));search='';audioQueue=[];window.speechSynthesis?.cancel();speaking=false;currentUtterance=null;persist();render();toast('Datos de ejemplo restablecidos.');}
 else if(action==='signout'){signedIn=false;try{sessionStorage.setItem('comal-demo-signed-out','true');}catch{}render();}
 else if(action==='signin'){signedIn=true;try{sessionStorage.removeItem('comal-demo-signed-out');}catch{}location.hash='caja';render();toast('Sesión de demostración iniciada.');}
 else if(action==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>toast('No se pudo salir de pantalla completa.',true));else document.documentElement.requestFullscreen?.().catch(()=>toast('Tu navegador no permite pantalla completa aquí. Abre la pantalla en otra ventana.',true));}
}
window.addEventListener('hashchange', () => { search=''; render(); window.scrollTo(0,0); });
window.addEventListener('storage', e => {
 if(e.key===AUDIO_STORAGE&&audioEnabled){const owner=audioOwner();if(owner&&owner.id!==tabId){setAudio(false);toast('El audio está activo en otra pestaña.');}return;}
 if(e.key!==STORAGE||!e.newValue)return;
 try{const next=JSON.parse(e.newValue);if(next.version!==1)return;const restoring=!state.connected&&next.connected,reset=next.demoResetId!==state.demoResetId;state=next;if(restoring||!next.connected||reset)knownCalls=new Set(state.calls.map(c=>c.id));if(!next.connected||reset){audioQueue=[];window.speechSynthesis?.cancel();speaking=false;currentUtterance=null;}render();processCalls();}catch{}
});
setInterval(()=>{if(audioEnabled){const owner=audioOwner();if(owner&&owner.id!==tabId&&Date.now()-owner.at<10000){setAudio(false);return;}try{localStorage.setItem(AUDIO_STORAGE,JSON.stringify({id:tabId,at:Date.now()}));}catch{}}},3000);
setInterval(()=>{if(route()==='pantalla'&&Q.ready(state).length>9){publicPage++;render();}},6000);
window.addEventListener('pagehide',()=>{try{if(audioOwner()?.id===tabId)localStorage.removeItem(AUDIO_STORAGE);}catch{}});
setInterval(() => { document.querySelectorAll('[data-clock]').forEach(el => el.textContent=time(Date.now())); document.querySelectorAll('[data-elapsed]').forEach(el => el.innerHTML=icon('clock')+' '+elapsed(+el.dataset.elapsed)); },15000);
persist(); render();
// Optional agent interface. These use the same actions and data as the visible UI.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const registerTool=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 registerTool({name:'read_comal_queue',title:'Consultar turnos',description:'Read this browser’s simulated Comal++ queue. Does not modify tickets.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{demo:true,connected:state.connected,orders:state.orders.filter(Q.active).map(({id,number,status})=>({id,number,status}))};}});
 registerTool({name:'register_comal_ticket',title:'Registrar ticket',description:'Register a printed ticket number in the cashier demo. Requires the cashier view and a signed-in demo session. Rejects active duplicates.',inputSchema:{type:'object',properties:{number:{type:'string',pattern:'^[0-9]{1,2}$'}},required:['number'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(route()!=='caja'||!signedIn)throw new Error('Abre el panel de caja con la sesión de demostración.');if(!input||typeof input.number!=='string')throw new Error('Se requiere el número de ticket.');syncLatest();const order=Q.register(state,input.number);persist();render();toast(`Ticket ${order.number} registrado.`);return{id:order.id,number:order.number,status:order.status};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
